const listPayments = `-- name: ListPayments :many
SELECT p.uuid, p.provider, p.method, p.status, p.currency, p.amount, p.gross_amount, p.commission_amount,
    p.net_amount, p.refunded_amount, p.provider_payment_id, p.verified_via, p.verified_at, p.outcome,
    p.failure_reason, p.note, p.created_at,
    r.uuid AS reservation_uuid, r.reference AS reservation_reference,
    l.uuid AS link_uuid,
    cu.uuid AS created_by_uuid, cu.name AS created_by_name, cu.surname AS created_by_surname, cu.email AS created_by_email,
    COUNT(*) OVER ()::bigint AS total
FROM payments p
JOIN reservations r ON r.organization_id = p.organization_id AND r.id = p.reservation_id
LEFT JOIN payment_links l ON l.organization_id = p.organization_id AND l.id = p.payment_link_id
LEFT JOIN users cu ON cu.id = p.created_by
WHERE p.organization_id = $1
  AND r.organization_id = $1
  AND (
    $2::bigint[] IS NULL
    OR r.pickup_branch_id = ANY($2::bigint[])
    OR r.return_branch_id = ANY($2::bigint[])
  )
  AND ($3::uuid[] IS NULL OR r.uuid = ANY($3::uuid[]))
  AND ($4::text[] IS NULL OR p.status = ANY($4::text[]))
  AND ($5::text[] IS NULL OR p.provider = ANY($5::text[]))
  AND (
    $6::text IS NULL
    OR r.reference ILIKE '%' || $6 || '%'
    OR p.provider_payment_id ILIKE '%' || $6 || '%'
  )
ORDER BY
    CASE WHEN $7::text = 'amount' AND NOT $8::boolean THEN p.amount END ASC,
    CASE WHEN $7::text = 'amount' AND $8::boolean THEN p.amount END DESC,
    CASE WHEN $7::text = 'created_at' AND NOT $8::boolean THEN p.created_at END ASC,
    CASE WHEN $7::text = 'created_at' AND $8::boolean THEN p.created_at END DESC,
    p.id DESC
LIMIT $10 OFFSET $9
`

