const sumReservationPayments = `-- name: SumReservationPayments :one
SELECT COALESCE(SUM(p.amount - p.refunded_amount), 0)::numeric(14, 2) AS paid,
    COALESCE(SUM(p.refunded_amount), 0)::numeric(14, 2) AS refunded
FROM payments p
WHERE p.organization_id = $1
  AND p.reservation_id = $2
  AND p.status IN ('succeeded', 'partially_refunded', 'refunded')
`

type SumReservationPaymentsParams struct {
	OrganizationID int64       `json:"organization_id"`
	ReservationID  pgtype.Int8 `json:"reservation_id"`
}

type SumReservationPaymentsRow struct {
	Paid     pgtype.Numeric `json:"paid"`
	Refunded pgtype.Numeric `json:"refunded"`
}

// What the reservation has received: amounts of confirmed payments minus
// their refunds, and the refunded total.
func (q *Queries) SumReservationPayments(ctx context.Context, arg SumReservationPaymentsParams) (SumReservationPaymentsRow, error) {
	row := q.db.QueryRow(ctx, sumReservationPayments, arg.OrganizationID, arg.ReservationID)
	var i SumReservationPaymentsRow
	err := row.Scan(&i.Paid, &i.Refunded)
	return i, err
}
